@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Inter:wght@400;500;600&display=swap');

:root {
  --background: #111111;
  --surface: #1A1A1A;
  --primary: #E63946;
  --primary-hover: #D90429;
  --text-main: #FFFFFF;
  --text-muted: #A3A3A3;
  --border: #333333;
  --radius: 4px;
  --font-heading: 'Bebas Neue', sans-serif;
  --font-body: 'Inter', sans-serif;
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-4: 1rem;
  --space-8: 2rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-24: 6rem;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--background);
  color: var(--text-main);
  font-family: var(--font-body);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  text-transform: uppercase;
  line-height: 1.1;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-4);
}

h1 { font-size: clamp(3rem, 8vw, 6rem); }
h2 { font-size: clamp(2rem, 5vw, 4rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2.5rem); }

a {
  color: var(--text-main);
  text-decoration: none;
  transition: color 200ms ease;
}

a:hover {
  color: var(--primary);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-4);
}

.section {
  padding: var(--space-16) 0;
}

.section-lg {
  padding: var(--space-24) 0;
}

.text-center { text-align: center; }
.text-primary { color: var(--primary); }
.text-muted { color: var(--text-muted); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1rem 2rem;
  font-family: var(--font-heading);
  font-size: 1.25rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  cursor: pointer;
  border: none;
  border-radius: 0;
  transition: all 200ms ease;
  text-decoration: none;
}

.btn-primary {
  background-color: var(--primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  color: white;
  transform: translateY(-2px);
}

.btn-outline {
  background-color: transparent;
  border: 2px solid white;
  color: white;
}

.btn-outline:hover {
  background-color: white;
  color: var(--background);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  background-color: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  z-index: 100;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-family: var(--font-heading);
  font-size: 2rem;
  color: var(--primary);
  letter-spacing: 0.05em;
}

.logo span {
  color: white;
}

.nav-links {
  display: flex;
  gap: var(--space-8);
  list-style: none;
}

.nav-links a {
  font-weight: 500;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nav-right {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: white;
  font-size: 1.5rem;
  cursor: pointer;
}

@media (max-width: 768px) {
  .nav-links, .nav-right .btn {
    display: none;
  }
  .mobile-menu-btn {
    display: block;
  }
}

/* Top Bar */
.top-bar {
  background-color: var(--primary);
  color: white;
  text-align: center;
  padding: var(--space-2);
  font-size: 0.875rem;
  font-weight: 500;
}

.top-bar a {
  text-decoration: underline;
  margin-left: 0.5rem;
}

.top-bar a:hover {
  color: #fff;
  opacity: 0.8;
}

/* Hero Section */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background-image: linear-gradient(rgba(17, 17, 17, 0.7), rgba(17, 17, 17, 0.9)), url('https://images.unsplash.com/photo-1534438327276-14e5300c3a48?q=80&w=1470&auto=format&fit=crop');
  background-size: cover;
  background-position: center;
}

.hero-content {
  max-width: 800px;
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-muted);
  margin-bottom: var(--space-8);
  max-width: 600px;
}

.hero-btns {
  display: flex;
  gap: var(--space-4);
  flex-wrap: wrap;
}

/* Grid Layouts */
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-8);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-8);
}

@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4 {
    grid-template-columns: 1fr;
  }
}

/* Cards */
.card {
  background-color: var(--surface);
  border: 1px solid var(--border);
  padding: var(--space-8);
  transition: transform 200ms ease, border-color 200ms ease;
}

.card:hover {
  transform: translateY(-4px);
  border-color: var(--primary);
}

/* Split Section */
.split-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 60vh;
}

.split-content {
  padding: var(--space-16) var(--space-8);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.split-image {
  background-size: cover;
  background-position: center;
}

@media (max-width: 768px) {
  .split-section {
    grid-template-columns: 1fr;
  }
  .split-image {
    min-height: 300px;
  }
}

/* CTA Section */
.cta-section {
  background-color: var(--primary);
  text-align: center;
  padding: var(--space-16) var(--space-4);
  color: white;
}

.cta-section h2 {
  margin-bottom: var(--space-4);
}

.cta-section .btn {
  background-color: var(--background);
  color: white;
}

.cta-section .btn:hover {
  background-color: white;
  color: var(--background);
}

/* Footer */
.footer {
  background-color: #000;
  padding: var(--space-16) 0 var(--space-8);
  border-top: 1px solid var(--border);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-8);
  margin-bottom: var(--space-16);
}

.footer-col h4 {
  color: white;
  margin-bottom: var(--space-4);
  font-size: 1.5rem;
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: var(--space-2);
}

.footer-links a {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.footer-links a:hover {
  color: var(--primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-8);
  border-top: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.8rem;
}

.country-select {
  background-color: var(--surface);
  color: white;
  border: 1px solid var(--border);
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }
}

/* Newsletter Form */
.newsletter-form {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-4);
  position: relative;
}

.newsletter-input {
  flex: 1;
  background-color: var(--surface);
  border: 1px solid var(--border);
  color: white;
  padding: 1rem;
  font-family: var(--font-body);
}

.newsletter-input:focus {
  outline: none;
  border-color: var(--primary);
}

.form-message {
  position: absolute;
  bottom: -25px;
  left: 0;
  font-size: 0.8rem;
}

.form-message.success { color: #4ade80; }
.form-message.error { color: var(--primary); }

/* Carousel */
.carousel-container {
  position: relative;
  overflow: hidden;
  width: 100%;
}

.carousel-track {
  display: flex;
  transition: transform 500ms ease-in-out;
}

.carousel-slide {
  min-width: 100%;
  height: 60vh;
  min-height: 400px;
  background-size: cover;
  background-position: center;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0,0,0,0.5);
  color: white;
  border: none;
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  transition: background 200ms;
}

.carousel-btn:hover {
  background: var(--primary);
}

.carousel-btn.prev { left: 20px; }
.carousel-btn.next { right: 20px; }

/* Toggle Group */
.toggle-group {
  display: flex;
  justify-content: center;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
}

.toggle-btn {
  background: transparent;
  border: 2px solid var(--border);
  color: var(--text-muted);
  padding: 0.75rem 2rem;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  cursor: pointer;
  transition: all 200ms;
}

.toggle-btn.active {
  border-color: var(--primary);
  color: var(--primary);
}

.toggle-content {
  display: none;
  animation: fadeIn 300ms ease-out forwards;
}

.toggle-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Instructor Filter */
.filter-bar {
  display: flex;
  gap: var(--space-2);
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: var(--space-8);
}

.filter-btn {
  background: var(--surface);
  border: 1px solid var(--border);
  color: white;
  padding: 0.5rem 1rem;
  cursor: pointer;
  transition: all 200ms;
}

.filter-btn.active, .filter-btn:hover {
  background: var(--primary);
  border-color: var(--primary);
}

.instructor-card img {
  width: 100%;
  aspect-ratio: 1/1;
  object-fit: cover;
  margin-bottom: var(--space-4);
  filter: grayscale(100%);
  transition: filter 300ms ease;
}

.instructor-card:hover img {
  filter: grayscale(0%);
}

.instructor-item {
  display: block;
}

.instructor-item.hidden {
  display: none;
}

/* FAQ Accordion */
.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: white;
  padding: var(--space-4) 0;
  font-size: 1.25rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq-question::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--primary);
}

.faq-item.active .faq-question::after {
  content: '−';
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease-out, padding 300ms ease;
  color: var(--text-muted);
}

.faq-item.active .faq-answer {
  max-height: 500px;
  padding-bottom: var(--space-4);
}

/* Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: var(--space-8);
}

.schedule-table th, .schedule-table td {
  padding: var(--space-4);
  border-bottom: 1px solid var(--border);
  text-align: left;
}

.schedule-table th {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  color: var(--primary);
}

.schedule-table tr:hover td {
  background-color: var(--surface);
}

/* Features List */
.feature-item {
  display: flex;
  gap: var(--space-4);
  margin-bottom: var(--space-8);
}

.feature-icon {
  width: 48px;
  height: 48px;
  background-color: var(--surface);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  flex-shrink: 0;
}

.feature-content h3 {
  margin-bottom: var(--space-2);
}

document.addEventListener('DOMContentLoaded', () => {

  // Mobile Menu
  const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
  const navLinks = document.querySelector('.nav-links');
  if (mobileMenuBtn && navLinks) {
    mobileMenuBtn.addEventListener('click', () => {
      navLinks.style.display = navLinks.style.display === 'flex' ? 'none' : 'flex';
      navLinks.style.flexDirection = 'column';
      navLinks.style.position = 'absolute';
      navLinks.style.top = '80px';
      navLinks.style.left = '0';
      navLinks.style.width = '100%';
      navLinks.style.background = 'rgba(17,17,17,0.95)';
      navLinks.style.padding = '2rem';
    });
  }

  // Newsletter Validation
  const newsletterForms = document.querySelectorAll('.newsletter-form');
  newsletterForms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = form.querySelector('.newsletter-input');
      const message = form.querySelector('.form-message');

      if (!input.value.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
        message.textContent = 'Please enter a valid email address.';
        message.className = 'form-message error';
      } else {
        message.textContent = 'Thank you for subscribing!';
        message.className = 'form-message success';
        input.value = '';
      }
    });
  });

  // Carousel
  const track = document.querySelector('.carousel-track');
  const slides = document.querySelectorAll('.carousel-slide');
  const nextBtn = document.querySelector('.carousel-btn.next');
  const prevBtn = document.querySelector('.carousel-btn.prev');

  if (track && slides.length > 0) {
    let currentIndex = 0;

    const updateCarousel = () => {
      track.style.transform = `translateX(-${currentIndex * 100}%)`;
    };

    nextBtn?.addEventListener('click', () => {
      currentIndex = (currentIndex + 1) % slides.length;
      updateCarousel();
    });

    prevBtn?.addEventListener('click', () => {
      currentIndex = (currentIndex - 1 + slides.length) % slides.length;
      updateCarousel();
    });

    // Simple swipe support
    let touchStartX = 0;
    let touchEndX = 0;
    track.addEventListener('touchstart', e => {
      touchStartX = e.changedTouches[0].screenX;
    }, {passive: true});
    track.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      if (touchStartX - touchEndX > 50) {
        currentIndex = (currentIndex + 1) % slides.length;
        updateCarousel();
      }
      if (touchEndX - touchStartX > 50) {
        currentIndex = (currentIndex - 1 + slides.length) % slides.length;
        updateCarousel();
      }
    }, {passive: true});
  }

  // Workout Toggle
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  const toggleContents = document.querySelectorAll('.toggle-content');
  if (toggleBtns.length > 0) {
    toggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const targetId = btn.getAttribute('data-target');

        toggleBtns.forEach(b => b.classList.remove('active'));
        toggleContents.forEach(c => c.classList.remove('active'));

        btn.classList.add('active');
        document.getElementById(targetId).classList.add('active');
      });
    });
  }

  // Instructor Filter
  const filterBtns = document.querySelectorAll('.filter-btn');
  const instructorItems = document.querySelectorAll('.instructor-item');
  if (filterBtns.length > 0) {
    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const filterValue = btn.getAttribute('data-filter');
        instructorItems.forEach(item => {
          if (filterValue === 'all' || item.getAttribute('data-location') === filterValue) {
            item.classList.remove('hidden');
          } else {
            item.classList.add('hidden');
          }
        });
      });
    });
  }

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  if (faqItems.length > 0) {
    faqItems.forEach(item => {
      const question = item.querySelector('.faq-question');
      question.addEventListener('click', () => {
        const isActive = item.classList.contains('active');

        // Single open behavior
        faqItems.forEach(i => i.classList.remove('active'));

        if (!isActive) {
          item.classList.add('active');
        }
      });
    });
  }
});
